[('新参与者','对象主动接受邀请且装置可用','先按真实能量条件执行，不为迎合需求临时无限启动。'),('对象抗拒','参与者坚持体验与真实生活不同','检查控制偏差并开放交流，不能把反对简单当作不存在。'),('事故外溢','意识或物质离开预定范围','追查实际影响，承认系统边界而非宣称一切仍在计划中。')],
[ev(2,3717,3767,'实验失败、尼格事故及能量限制'),ev(2,3783,3795,'机制与返回'),ev(2,3827,3827,'未找到设备')],
